describe("doctests of sympy.simplify.powsimp", () => {
  // the arguments do not type-check against the public API
  //   powdenest((x**(2*a/3))**(3*x))
  //   => (x**(2*a/3))**(3*x)
  it.todo("powdenest((x**(2*a/3))**(3*x))");
  it("powdenest(exp(3*x*log(2)))", () => {
    const x = new Sym('x');
    expect(sympyStr(powdenest(new Pow(E, mul(Rational.of(3n, 1n, { gcd: 1n }), x, fn('log', [Rational.of(2n, 1n, { gcd: 1n })], { evaluate: false }))), { force: false }))).toBe('2**(3*x)');
  });
  // the arguments do not type-check against the public API
  //   powdenest(sqrt(x**2))
  //   => sqrt(x**2)
  it.todo("powdenest(sqrt(x**2))");
  it("powdenest(sqrt(p**2))", () => {
    const p = new Sym('p', { positive: true });
    expect(sympyStr(powdenest(p, { force: false }))).toBe('p');
  });
  it("powdenest((x**x)**(i + j)) # -X-> (x**x)**i*(x**x)**j", () => {
    const x = new Sym('x');
    const i = new Sym('i', { integer: true });
    const j = new Sym('j', { integer: true });
    expect(sympyStr(powdenest(pow(x, mul(x, add(i, j))), { force: false }))).toBe('x**(x*(i + j))');
  });
  it("powdenest(exp(3*y*log(x)))", () => {
    const [y, x] = symbols('y x');
    expect(sympyStr(powdenest(new Pow(E, mul(Rational.of(3n, 1n, { gcd: 1n }), y, fn('log', [x], { evaluate: false }))), { force: false }))).toBe('x**(3*y)');
  });
  it("powdenest(exp(y*(log(a) + log(b))))", () => {
    const [y, a, b] = symbols('y a b');
    expect(sympyStr(powdenest(new Pow(E, mul(y, add(fn('log', [a], { evaluate: false }), fn('log', [b], { evaluate: false })))), { force: false }))).toBe('(a*b)**y');
  });
  it("powdenest(exp(3*(log(a) + log(b))))", () => {
    const [a, b] = symbols('a b');
    expect(sympyStr(powdenest(mul(pow(a, Rational.of(3n, 1n, { gcd: 1n })), pow(b, Rational.of(3n, 1n, { gcd: 1n }))), { force: false }))).toBe('a**3*b**3');
  });
  // the arguments do not type-check against the public API
  //   powdenest(((x**(2*i))**(3*y))**x)
  //   => ((x**(2*i))**(3*y))**x
  it.todo("powdenest(((x**(2*i))**(3*y))**x)");
  // the arguments do not type-check against the public API
  //   powdenest(((x**(2*i))**(3*y))**x, force=True)
  //   => x**(6*i*x*y)
  it.todo("powdenest(((x**(2*i))**(3*y))**x, force=True)");
  // the arguments do not type-check against the public API
  //   powdenest(((x**(2*a/3))**(3*y/i))**x)
  //   => ((x**(2*a/3))**(3*y/i))**x
  it.todo("powdenest(((x**(2*a/3))**(3*y/i))**x)");
  it("powdenest((x**(2*i)*y**(4*i))**z, force=True)", () => {
    const [x, y, z] = symbols('x y z');
    const i = new Sym('i', { integer: true });
    expect(sympyStr(powdenest(pow(mul(pow(x, mul(Rational.of(2n, 1n, { gcd: 1n }), i)), pow(y, mul(Rational.of(4n, 1n, { gcd: 1n }), i))), z), { force: true }))).toBe('(x*y**2)**(2*i*z)');
  });
  // the arguments do not type-check against the public API
  //   powdenest((x**i)**y, force=True)
  //   => x**(i*y)
  it.todo("powdenest((x**i)**y, force=True)");
  // the arguments do not type-check against the public API
  //   powdenest((n**i)**x, force=True)
  //   => (n**i)**x
  it.todo("powdenest((n**i)**x, force=True)");
  it("powsimp(x**y*x**z*y**z, combine='all')", () => {
    const [x, y, z] = symbols('x y z');
    expect(sympyStr(powsimp(mul(pow(x, y), pow(x, z), pow(y, z)), { combine: 'all' }))).toBe('x**(y + z)*y**z');
  });
  it("powsimp(x**y*x**z*y**z, combine='exp')", () => {
    const [x, y, z] = symbols('x y z');
    expect(sympyStr(powsimp(mul(pow(x, y), pow(x, z), pow(y, z)), { combine: 'exp' }))).toBe('x**(y + z)*y**z');
  });
  it("powsimp(x**y*x**z*y**z, combine='base', force=True)", () => {
    const [x, y, z] = symbols('x y z');
    expect(sympyStr(powsimp(mul(pow(x, y), pow(x, z), pow(y, z)), { combine: 'base', force: true }))).toBe('x**y*(x*y)**z');
  });
  it("powsimp(x**z*x**y*n**z*n**y, combine='all', force=True)", () => {
    const [n, y, z, x] = symbols('n y z x');
    expect(sympyStr(powsimp(mul(pow(n, y), pow(n, z), pow(x, y), pow(x, z)), { combine: 'all', force: true }))).toBe('(n*x)**(y + z)');
  });
  it("powsimp(x**z*x**y*n**z*n**y, combine='exp')", () => {
    const [n, y, z, x] = symbols('n y z x');
    expect(sympyStr(powsimp(mul(pow(n, y), pow(n, z), pow(x, y), pow(x, z)), { combine: 'exp' }))).toBe('n**(y + z)*x**(y + z)');
  });
  it("powsimp(x**z*x**y*n**z*n**y, combine='base', force=True)", () => {
    const [n, y, z, x] = symbols('n y z x');
    expect(sympyStr(powsimp(mul(pow(n, y), pow(n, z), pow(x, y), pow(x, z)), { combine: 'base', force: true }))).toBe('(n*x)**y*(n*x)**z');
  });
  it("powsimp(log(exp(x)*exp(y)))", () => {
    const x = new Sym('x', { positive: true });
    const y = new Sym('y', { positive: true });
    expect(sympyStr(powsimp(fn('log', [mul(new Pow(E, x), new Pow(E, y))], { evaluate: false }), {}))).toBe('log(exp(x)*exp(y))');
  });
  it("powsimp(log(exp(x)*exp(y)), deep=True)", () => {
    const x = new Sym('x', { positive: true });
    const y = new Sym('y', { positive: true });
    expect(sympyStr(powsimp(fn('log', [mul(new Pow(E, x), new Pow(E, y))], { evaluate: false }), { deep: true }))).toBe('x + y');
  });
  it("a*a**3 == a**4", () => {
    const [y, x] = symbols('y x');
    expect(sympyStr(mul(y, pow(x, Rational.of(2n, 1n, { gcd: 1n }))).equals(mul(y, pow(x, Rational.of(2n, 1n, { gcd: 1n })))))).toBe('True');
  });
  it("a**4 # auto expands to a Mul, no longer a Pow", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(pow(mul(x, pow(y, Rational.of(1n, 2n, { gcd: 1n }))), Rational.of(1n, 2n, { gcd: 1n })).pow(4))).toBe('x**2*y');
  });
  it("powsimp(x*y*a) # but won't when doing so would violate assumptions", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(powsimp(mul(x, y, pow(mul(x, pow(y, Rational.of(1n, 2n, { gcd: 1n }))), Rational.of(1n, 2n, { gcd: 1n }))), {}))).toBe('x*y*sqrt(x*sqrt(y))');
  });
});

